<?php
require_once __DIR__.'/../config/database.php';require_admin();$tables=['users'=>'Students','lessons'=>'Lessons','resources'=>'Multimedia resources','activities'=>'Simulations','quizzes'=>'Quizzes'];$counts=[];foreach($tables as $t=>$label)$counts[$label]=(int)$conn->query("SELECT COUNT(*) FROM {$t}")->fetchColumn();$q=$conn->query('SELECT u.fullname,u.email,q.title,a.score,a.total,a.attempted_at FROM quiz_attempts a JOIN users u ON u.id=a.user_id JOIN quizzes q ON q.id=a.quiz_id ORDER BY a.attempted_at DESC LIMIT 8')->fetchAll();$pageTitle='Admin overview';require __DIR__.'/../partials/header.php'; ?>
<section class="dashboard-hero admin-hero"><div><span class="eyebrow">ADMINISTRATION</span><h1>Platform overview</h1><p>Welcome, <?= e($_SESSION['fullname']) ?>. Manage the learning space and review student activity.</p></div><a class="button button-primary" href="<?= e(app_url('admin/manage.php')) ?>">Manage content <span>↗</span></a></section><section class="content-wrap dashboard-content"><div class="metric-grid admin-metrics"><?php foreach($counts as $label=>$count): ?><a class="metric-card" href="<?= e(app_url('admin/manage.php?section='.urlencode(strtolower(str_replace(' ','-',$label))))) ?>"><span><?= e($label) ?></span><strong><?= $count ?></strong><small>Manage ↗</small></a><?php endforeach; ?></div><div class="admin-links"><?php foreach(['students'=>'Manage Students','lessons'=>'Manage Lessons','multimedia'=>'Manage Multimedia','simulation'=>'Manage Simulation','quizzes'=>'Manage Quizzes','results'=>'View Student Results','reports'=>'Generate Reports'] as $k=>$label): ?><a href="<?= e(app_url('admin/manage.php?section='.$k)) ?>"><span><?= e($label) ?></span><b>↗</b></a><?php endforeach; ?></div><section class="panel"><div class="section-heading"><div><span class="eyebrow">LEARNER ACTIVITY</span><h2>Recent quiz results</h2></div><a class="text-link" href="<?= e(app_url('admin/manage.php?section=reports')) ?>">Generate report ↗</a></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Quiz</th><th>Score</th><th>Date</th></tr></thead><tbody><?php foreach($q as $a): ?><tr><td><?= e($a['fullname']) ?><small><?= e($a['email']) ?></small></td><td><?= e($a['title']) ?></td><td><?= (int)$a['score'] ?>/<?= (int)$a['total'] ?></td><td><?= e(date('M j, Y',strtotime($a['attempted_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div></section></section><?php require __DIR__.'/../partials/footer.php'; ?>
